// 输出成片：无头 Chrome 逐帧画 Canvas，ffmpeg 编码，再混入 music.mjs 合成的配乐。
// 用法：node render.mjs                     全片
//      node render.mjs --stills 0,90,135 目录   只输出指定帧号的 PNG
import {spawn, spawnSync} from 'node:child_process';
import {mkdirSync, rmSync, statSync, writeFileSync} from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {openChrome} from '../../會呼吸的痛/開場樣圖/v2/chrome.mjs';
import {FPS, FRAME_COUNT} from './timeline.js';
import {synthesize, toWav} from './music.mjs';

const here = path.dirname(fileURLToPath(import.meta.url));
const OUT_DIR = path.join(here, '输出');
const PARTS = path.join(OUT_DIR, '分段');
const WAV = path.join(OUT_DIR, '配乐.wav');
const TARGET = path.join(OUT_DIR, '如何在算法时代保持清醒.mp4');
const WORKERS = 3;
const ENCODE = ['-c:v', 'libx264', '-preset', 'medium', '-crf', '16', '-threads', '2', '-g', String(FPS), '-bf', '0',
  '-vf', 'scale=out_color_matrix=bt709:out_range=tv:flags=lanczos+accurate_rnd+full_chroma_int,format=yuv420p',
  '-colorspace', 'bt709', '-color_primaries', 'bt709', '-color_trc', 'bt709', '-color_range', 'tv', '-r', String(FPS)];
const IMAGE = `document.getElementById('stage').toDataURL('image/png').split(',')[1]`;

async function renderSegment(chrome, first, count, file) {
  const ffmpeg = spawn('ffmpeg', ['-y', '-loglevel', 'error', '-f', 'image2pipe', '-framerate', String(FPS), '-c:v', 'png', '-i', '-', ...ENCODE, file], {stdio: ['pipe', 'inherit', 'inherit']});
  const finished = new Promise((ok, fail) => ffmpeg.once('exit', code => (code === 0 ? ok() : fail(new Error(`ffmpeg 退出 ${code}`)))));
  for (let n = first; n < first + count; n++) {
    await chrome.evaluate(`window.film.renderFrame(${n})`);
    const image = Buffer.from(await chrome.evaluate(IMAGE), 'base64');
    if (!ffmpeg.stdin.write(image)) await new Promise(ok => ffmpeg.stdin.once('drain', ok));
  }
  ffmpeg.stdin.end();
  await finished;
  const errors = await chrome.evaluate('window.renderErrors');
  if (errors.length) throw new Error(JSON.stringify(errors));
}

async function renderAll() {
  const started = Date.now();
  rmSync(PARTS, {recursive: true, force: true});
  mkdirSync(PARTS, {recursive: true});
  writeFileSync(WAV, toWav(synthesize()));
  const size = Math.ceil(FRAME_COUNT / WORKERS);
  const segments = Array.from({length: WORKERS}, (_, i) => ({first: i * size, count: Math.min(size, FRAME_COUNT - i * size), file: path.join(PARTS, `part-${i}.mp4`)}));
  await Promise.all(segments.map(async s => {
    const chrome = await openChrome();
    try {
      await chrome.openStyle('film', here);
      await renderSegment(chrome, s.first, s.count, s.file);
    } finally {
      await chrome.close();
    }
  }));
  const list = path.join(PARTS, 'list.txt');
  writeFileSync(list, segments.map(s => `file '${path.basename(s.file)}'`).join('\n') + '\n');
  const mux = spawnSync('ffmpeg', ['-y', '-loglevel', 'error', '-f', 'concat', '-safe', '0', '-i', list, '-i', WAV,
    '-map', '0:v:0', '-map', '1:a:0', '-c:v', 'copy', '-c:a', 'aac', '-b:a', '256k', '-ar', '48000',
    '-map_metadata', '-1', '-movflags', '+faststart', '-t', '30', TARGET], {stdio: 'inherit'});
  if (mux.status !== 0) throw new Error(`拼接失败 ${mux.status}`);
  rmSync(PARTS, {recursive: true, force: true});
  const result = {frames: FRAME_COUNT, fps: FPS, megabytes: Number((statSync(TARGET).size / 1048576).toFixed(1)), seconds: Math.round((Date.now() - started) / 1000)};
  writeFileSync(path.join(OUT_DIR, '渲染结果.json'), JSON.stringify(result, null, 2) + '\n');
  console.log(JSON.stringify(result));
}

async function renderStills(frames, dir) {
  mkdirSync(dir, {recursive: true});
  const chrome = await openChrome();
  try {
    await chrome.openStyle('film', here);
    for (const n of frames) {
      await chrome.evaluate(`window.film.renderFrame(${n})`);
      writeFileSync(path.join(dir, `f${String(n).padStart(3, '0')}.png`), Buffer.from(await chrome.evaluate(IMAGE), 'base64'));
    }
    const errors = await chrome.evaluate('window.renderErrors');
    if (errors.length) throw new Error(JSON.stringify(errors));
  } finally {
    await chrome.close();
  }
}

const args = process.argv.slice(2);
if (args[0] === '--stills') await renderStills(args[1].split(',').map(Number), path.resolve(args[2]));
else await renderAll();
// 检查导出的 MP4：规格、每次翻页在哪一帧落定、解码后的音轨重音是否在同一拍点、响度。
// 用法：node verify-export.mjs
import {spawnSync} from 'node:child_process';
import {writeFileSync} from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {FPS, FLIP_FRAMES, FRAME_COUNT, PAGES} from './timeline.js';

const here = path.dirname(fileURLToPath(import.meta.url));
const VIDEO = path.join(here, '输出/如何在算法时代保持清醒.mp4');
const run = (cmd, args, opts = {}) => {
  const r = spawnSync(cmd, args, {maxBuffer: 1 << 30, ...opts});
  if (r.status !== 0) throw new Error(`${cmd} 退出 ${r.status}: ${r.stderr}`);
  return r;
};

const probe = JSON.parse(run('ffprobe', ['-v', 'error', '-count_frames', '-show_streams', '-show_format', '-of', 'json', VIDEO]).stdout);
const v = probe.streams.find(s => s.codec_type === 'video');
const a = probe.streams.find(s => s.codec_type === 'audio');

// 缩到 192×108 灰度，逐帧比较平均差。
const SW = 192, SH = 108;
const raw = run('ffmpeg', ['-v', 'error', '-i', VIDEO, '-vf', `scale=${SW}:${SH},format=gray`, '-f', 'rawvideo', '-']).stdout;
const frames = raw.length / (SW * SH);
const diff = [0];
for (let f = 1; f < frames; f++) {
  let s = 0;
  for (let i = 0; i < SW * SH; i++) s += Math.abs(raw[f * SW * SH + i] - raw[(f - 1) * SW * SH + i]);
  diff.push(s / (SW * SH));
}
// 翻页的最后几帧画面仍在大幅变化，拍点那一帧之后立即静止，才算落在拍上。
const flips = PAGES.slice(1).map(p => {
  const during = diff.slice(p.land - 4, p.land + 1);
  const after = diff.slice(p.land + 1, p.land + 4);
  let lastMoving = p.land - FLIP_FRAMES;
  for (let f = p.land - FLIP_FRAMES; f <= p.land + 3; f++) if (diff[f] > 1.5) lastMoving = f;
  return {page: p.id, land: p.land, seconds: p.land / FPS, lastMovingFrame: lastMoving,
    minDuring: Number(Math.min(...during).toFixed(2)), maxAfter: Number(Math.max(...after).toFixed(2)),
    settled: lastMoving === p.land && Math.min(...during) > 1.5 && Math.max(...after) < 1};
});

const SR = 48000;
const pcm = run('ffmpeg', ['-v', 'error', '-i', VIDEO, '-map', '0:a:0', '-ac', '1', '-ar', String(SR), '-f', 'f32le', '-']).stdout;
const samples = new Float32Array(pcm.buffer, pcm.byteOffset, pcm.length / 4);
const win = SR / 100;
const energy = s0 => { let e = 0; for (let i = s0; i < s0 + win; i++) e += samples[i] ** 2; return e; };
const onsets = PAGES.slice(1).map(p => {
  const center = Math.round(p.land / FPS * SR);
  let best = center, bestRise = -Infinity;
  for (let s = center - SR * 0.03; s <= center + SR * 0.03; s += SR / 1000) {
    const rise = energy(s) - energy(s - win);
    if (rise > bestRise) { bestRise = rise; best = s; }
  }
  return {page: p.id, offsetMs: Math.round((best - center) / SR * 1000)};
});

const loud = run('ffmpeg', ['-hide_banner', '-nostats', '-i', VIDEO, '-map', '0:a:0', '-af', 'ebur128=peak=true', '-f', 'null', '-']).stderr.toString();
const summary = loud.slice(loud.lastIndexOf('Summary:'));
const num = re => Number(summary.match(re)?.[1]);

const result = {
  video: {width: v.width, height: v.height, fps: v.r_frame_rate, frames: Number(v.nb_read_frames), codec: v.codec_name, pix: v.pix_fmt},
  audio: {codec: a.codec_name, sampleRate: Number(a.sample_rate), channels: a.channels},
  duration: Number(probe.format.duration),
  flips,
  onsets,
  loudness: {integratedLUFS: num(/I:\s+(-?[\d.]+) LUFS/), truePeakDBFS: num(/Peak:\s+(-?[\d.]+) dBFS/)},
};
result.ok = result.video.width === 1920 && result.video.height === 1080 && result.video.fps === '30/1' && result.video.frames === FRAME_COUNT
  && Math.abs(result.duration - 30) < 0.05 && flips.every(f => f.settled) && onsets.every(o => Math.abs(o.offsetMs) <= 5)
  && result.loudness.integratedLUFS >= -18 && result.loudness.integratedLUFS <= -14 && result.loudness.truePeakDBFS <= -0.5;
writeFileSync(path.join(here, '输出/导出检查.json'), JSON.stringify(result, null, 2) + '\n');
console.log(JSON.stringify(result, null, 2));
if (!result.ok) process.exit(1);
