    g.font = font(70, 900); g.fillStyle = INK; g.textAlign = 'center'; g.textBaseline = 'alphabetic';
    g.fillText(MOTTO.lines[0], cx, cy - 12); g.fillText(MOTTO.lines[1], cx, cy + 82);
    g.textAlign = 'left';
